  222 |         }
  223 |         ConcreteFileVersion::V2_0
  224 |         | ConcreteFileVersion::V2_1
  225 |         | ConcreteFileVersion::V2_2
  226 |         | ConcreteFileVersion::V2_3 => {}
  227 |     }
  228 | 
  229 |     do_write_manifest(writer, manifest, indices, transaction).await
  230 | }
